class Solution {
public:
    string getHint(string secret, string guess) {
        int bulls = 0;
        int cntS[10] = {0};
        int cntG[10] = {0};
        int n = secret.size();
        for (int i = 0; i < n; ++i) {
            if (secret[i] == guess[i]) {
                ++bulls;
            } else {
                ++cntS[secret[i] - '0'];
                ++cntG[guess[i] - '0'];
            }
        }
        int cows = 0;
        for (int d = 0; d < 10; ++d) {
            cows += min(cntS[d], cntG[d]);
        }
        return to_string(bulls) + "A" + to_string(cows) + "B";
    }
};
